.strip .fader-tools,#masterLeft .master-tools{position:relative;z-index:1;isolation:isolate}
.strip .strip-name,#masterLeft .master-strip-name{position:relative;z-index:2;isolation:isolate}
/* No odd vertical displacement of the active nav relative to its neighbors. */

/* Issue #56: passive hover has no filter or animated shadow.
   Preserve all seven resting / seven pressed shadows and 1px tactile response.
   Historical brightness is isolated to opt-in baseline A/B only. */

/* Hardware tactility: brief pointer/keyboard activation presses the SAME cap
   1px into the control panel. The layout and hit target stay the same; only
   the rendered face shifts, while the lower cast shadow collapses inward.
   Identical response for gray OFF and colored ON; no persistent pressed skin. */
:is(.btn-180,.toolbar .nav button.btn-180,.toolbar .spec-device,
 .strip .channel-actions .candy,.strip .utility-row button,.strip .fader-tools button,
 #masterLeft .master-actions button,#masterLeft .master-tools button,
 .left-rail .tabs button.btn-180,.left-rail .rail-presets button.btn-180,
 .left-rail .rail-bottom button.btn-180,.native-btn):active:not(:disabled){
 transform:translateY(1px)!important;
 box-shadow:
  inset 3px 2px 2px -1px rgba(0,0,0,.50),
  inset 0 0 1px 0 rgba(255,255,255,.14),
  inset 0 1px 15px rgba(0,0,0,.29),
  inset 0 -1px 2px rgba(0,0,0,.32),
  0 0 0 1px var(--b180-border),
  0 1px 1px rgba(0,0,0,.28),
  0 2px 3px rgba(0,0,0,.13)!important;
}

/* OFF uses the same shared material with a brighter light-steel face.
   Bright ON color recipes above remain untouched. */
:is(.toolbar .spec-device,
 .strip .channel-actions .candy,.strip .utility-row button,
 #masterLeft .master-actions button,#masterLeft .master-tools button,
 .left-rail .tabs button.btn-180,.left-rail .rail-presets button.btn-180,
 .left-rail .rail-bottom button.btn-180):not(.active):not(.selected):not(.on):not([aria-pressed="true"]){
 --b180-color:var(--b180-off);--b180-border:var(--b180-edge);
 --b180-ink:var(--b180-off-ink);
 color:var(--b180-ink)!important;
}
@media(prefers-reduced-motion:reduce){
 :is(.toolbar .nav button.btn-180,.toolbar .spec-device,.strip .channel-actions .candy,
 .strip .utility-row button,.left-rail button.btn-180){transition:none!important}
}

