#app .toolbar-actions .nav button.btn-180 > span{transform:none!important;transition:none!important}

/* Device is a standard toolbar-size BTN-180 pad, not the old cyan-caption spec.
   Green indicates verified connected native audio status only. Preview is OFF. */
#app .toolbar .spec-device{
 height:34px;min-height:34px;
 padding:0 10px!important;letter-spacing:.35px!important;
}
#app .toolbar .spec-device #headerDriver{
