 --b180-border:#3a9b68;
 --b180-ink:#113322;
}
/* Toolbar actions are NEUTRAL when idle, green only for selected/active.
   One solid repaint on state change, never a hover filter or glow. */
#app .toolbar-actions .nav button.btn-180:not(.selected):not(.active):not([aria-pressed="true"]){
 --b180-color:var(--b180-off);--b180-border:var(--b180-edge);
 --b180-ink:var(--b180-off-ink);
}
#app .toolbar-actions .nav button.btn-180:is(.selected,.active,[aria-pressed="true"]){
 --b180-color:#b2e8a0;--b180-border:#649c62;--b180-ink:#1a361d;
}
